from lib import *
S = SS('v94')
steps = [
    step("Ingress 能表达什么(Traefik v3.7.15 的 Ingress provider,kind 集群,客户端在集群里)。host shop.local:/a 路由到 app-v1,/b 路由到 app-v2:各请求 200 个,/a 全部返回 v1,/b 全部返回 v2。想让 / 的流量按比例分给两个 Service,只能写两条 path 都是 / 的规则:先写 app-v1,后写 app-v2,请求 200 个全部返回 v2,没有按比例分。kubectl explain 列出的字段:paths 下只有 backend、path、pathType,rules 下只有 host 和 http。没有权重、没有请求头匹配,这类需求只能用具体控制器的注解或自定义资源。", t=tl(S(1)), mark=lidx(S(1), '(b)两条 path', '(c)kubectl explain ingress.spec.rules.http.paths'), done=lidx(S(1), '(a)GET /a'), b=bars([['/a 返回 v1(共 200)', 200, '200'], ['/b 返回 v2(共 200)', 200, '200'], ['两条 / 规则:返回 v2(共 200)', 200, '200(没有分流)'], ['两条 / 规则:返回 v1', 0, '0']], 200, done=[0, 1], mark=[2, 3]), kv=KV([['按路径分', '可以'], ['按比例分', '没有这个字段'], ['按请求头分', '没有这个字段'], ['同一路径写两条', '全部去了同一个后端']], ['按比例分'])),
    step("Gateway API 的 HTTPRoute(同一个 Traefik,Gateway 监听 8000)。权重 90 对 10:500 个请求 v1 得 450、v2 得 50。改成 50 对 50:各 250。改成 0 对 100:500 个全是 v2。请求头匹配(带 x-canary: 1 的请求去 app-v2,其它去 app-v1):带头 200 个全是 v2,不带头 200 个全是 v1。权重和请求头匹配是 HTTPRoute 规范里的字段,不是某个控制器的注解;这个实现的分配是精确的比例,不是随机抽样。", t=tl(S(2)), mark=lidx(S(2), '(b)权重 50 对 50', '(c)权重 0 对 100'), done=lidx(S(2), '(a)app-v1 权重 90', '(d)带 x-canary: 1'), b=bars([['90/10:v2 得到', 50, '50(共 500)'], ['50/50:v2 得到', 250, '250(共 500)'], ['0/100:v2 得到', 500, '500(共 500)'], ['带 x-canary 头:v2 得到', 200, '200(共 200)']], 500, done=[0, 3], cur=[1], mark=[2]), kv=KV([['权重 90 对 10', 'v1 450 / v2 50'], ['权重 50 对 50', '250 / 250'], ['权重 0 对 100', '全部 v2'], ['请求头匹配', '带头全 v2,不带头全 v1']], ['权重 90 对 10'])),
    step("谁能把路由挂到谁的网关上。Gateway 在命名空间 v94,监听器 allowedRoutes 先是 from: Same;命名空间 v94b 里的 HTTPRoute 指向它。(a)from: Same:路由状态 Accepted=False(NotAllowedByListeners),请求 other.local 得到 404 × 100。(b)改成 from: All:Accepted=True,200 返回 v3 × 100。(c)路由再引用 v94 里的 Service,没有 ReferenceGrant:ResolvedRefs=False(RefNotPermitted),请求得到 500 × 100。(d)在 v94 里加 ReferenceGrant:ResolvedRefs=True,200 返回 v1 × 100。这两层授权是规范规定的,Ingress 没有。", t=tl(S(3)), mark=lidx(S(3), '(a)from: Same', '(c)后端是另一个命名空间'), done=lidx(S(3), '(b)from: All', '(d)加上 ReferenceGrant'), b=bars([['(a)Same:请求成功数', 0, '0(404 × 100)'], ['(b)All:请求成功数', 100, '100'], ['(c)缺 ReferenceGrant:请求成功数', 0, '0(500 × 100)'], ['(d)有 ReferenceGrant:请求成功数', 100, '100']], 100, mark=[0, 2], done=[1, 3]), kv=KV([['Same', 'NotAllowedByListeners → 404'], ['All', 'Accepted → 200'], ['缺 ReferenceGrant', 'RefNotPermitted → 500'], ['有 ReferenceGrant', 'ResolvedRefs → 200']], ['缺 ReferenceGrant'])),
    step("配置错了,从 kubectl 能看到什么。(a)Ingress 指向不存在的 Service:status 只有 {\"loadBalancer\": {}},请求得到 404 × 100,kubectl 看不出哪里错了。(b)HTTPRoute 的 backendRef 指向不存在的 Service:Accepted=True,ResolvedRefs=False(BackendNotFound),message 是 Cannot load HTTPBackendRef v94/no-such-svc: getting service: service \"no-such-svc\" not found,请求得到 500 × 100。HTTPRoute 的状态条件是规范规定的,控制器必须写;Ingress 的 status 里只有负载均衡器地址。", t=tl(S(4)), mark=lidx(S(4), '(a)Ingress 指向不存在的 Service'), done=lidx(S(4), '(b)HTTPRoute 指向不存在的 Service', '(b)ResolvedRefs 的 message'), b=bars([['(a)Ingress:status 里的错误信息条数', 0, '0'], ['(b)HTTPRoute:ResolvedRefs=False 的条数', 1, '1(BackendNotFound)'], ['(a)请求返回 404', 100, '100'], ['(b)请求返回 500', 100, '100']], 100, mark=[0], done=[1], cur=[2, 3]), kv=KV([['Ingress', 'status: loadBalancer 空,404'], ['HTTPRoute', 'ResolvedRefs=False(BackendNotFound),500'], ['谁告诉你错在哪', 'HTTPRoute 的 status 条件'], ['Ingress', '得去看控制器日志']], ['谁告诉你错在哪'])),
    step("改一次配置要多久生效:把流量从 app-v1 全部切到 app-v2,客户端每 20 ms 请求一次,从宿主机 kubectl apply 开始算(含 kubectl 进程本身),各 5 次。Ingress 改后端 Service:中位数 0.11 s(0.08 到 0.17 s)。HTTPRoute 改权重 100/0 到 0/100:中位数 0.22 s(0.12 到 0.28 s)。两者都在 0.3 s 以内,时钟对表的误差在 0.1 s 量级,所以不能说哪一种更快。两种写法最终都是同一个控制器监听对象再更新数据面,换控制器数字会不同。", t=tl(S(5)), mark=lidx(S(5), 'HTTPRoute:从'), done=lidx(S(5), 'Ingress:从'), b=bars([['Ingress 中位数 ms', 110, '110'], ['HTTPRoute 中位数 ms', 220, '220']], 300, cur=[0, 1]), kv=KV([['Ingress', '中位数 0.11 s'], ['HTTPRoute', '中位数 0.22 s'], ['测量误差', '0.1 s 量级,差别不可信'], ['结论', '都在 0.3 s 以内']], ['结论'])),
]
A = mkartv('v94', 94, '微服务,Kubernetes,Ingress,Gateway API,HTTPRoute,Traefik,真实验证,动画演示',
    '实测 Ingress 和 Gateway API(Traefik v3.7.15,同一个数据面):Ingress 只能按 host 和 path 选一个后端,同一路径写两条规则全部去了同一个后端;HTTPRoute 的权重(90/10 得到 450/50)和请求头匹配是规范字段;跨命名空间要过 allowedRoutes 和 ReferenceGrant;HTTPRoute 状态会说明错在哪,Ingress 不会;两种写法的生效都在 0.3 s 内。',
    'Ingress 和 Gateway API 到底差在哪?流量比例、请求头匹配能不能直接写在规范里?谁能把路由挂到网关上?配置写错了 kubectl 能告诉你什么?这篇用 kind 集群里同一个 Traefik 同时跑 Ingress 和 Gateway API 两种写法,逐项量出来。',
    [('450 / 50', 'HTTPRoute 权重 90 对 10 时,500 个请求里 v1 与 v2 各得多少(规范字段,不是注解)'), ('404 / 500', '同样是指向不存在的 Service:Ingress 请求得 404 且 status 没有信息,HTTPRoute 请求得 500 且有 BackendNotFound'), ('< 0.3 s', 'Ingress 与 HTTPRoute 切流量从 kubectl apply 到客户端看到新后端的时间(含 kubectl 进程)')],
    [('Ingress 的边界', '<p>规则只有 host、path、pathType 和一个后端 Service,没有权重和请求头匹配;按比例分流要靠控制器的注解或自定义资源。</p>'),
     ('HTTPRoute', '<p>权重和请求头匹配是规范里的字段,这个实现按精确的比例分配。</p>'),
     ('跨命名空间', '<p>路由要经过监听器的 allowedRoutes 才能挂上去,引用别的命名空间的 Service 要对方用 ReferenceGrant 授权,规范规定了越界时的行为。</p>'),
     ('错误可见性', '<p>HTTPRoute 的状态条件会写明 BackendNotFound、RefNotPermitted 这类原因;Ingress 的 status 里只有地址。</p>'),
     ('生效速度', '<p>两种写法都在 0.3 s 以内生效,差别在测量误差内。</p>')],
    steps,
    [ENV_V + '。kind 集群,Gateway API 标准通道 CRD v1.6.3,Traefik v3.7.15(同时开启 Ingress 与 Gateway API 两个 provider,同一个数据面);后端是 busybox httpd;客户端是集群里的 Pod;全部是这一个实现的结果,其它控制器(ingress-nginx、Envoy Gateway、Istio)的注解和对 Gateway API 特性的支持程度不同;每个场景只跑了一次,传播延迟是 5 次,从宿主机 kubectl apply 开始算,时钟差用 kubectl exec 对表估计,误差在 0.1 s 量级;开发时在另一次运行里,同一个 host 和 path 在两个命名空间里各有一条 HTTPRoute,Traefik 只让先创建的那条生效(日志里有 does not create router 的警告),这个行为没有单独做成实验',
     '没有验证:TLS 终止与证书(Gateway 的 certificateRefs、Ingress 的 tls);ingress-nginx 等其它控制器(我记得 ingress-nginx 项目已经宣布停止维护,没有核实,也没有测);GRPCRoute、TCPRoute 与实验通道的特性;多个 Gateway 共享一个入口;云上负载均衡器后面的行为(kind 里没有 LoadBalancer);Traefik 对权重分配是否在所有版本里都是精确比例;大规模路由(上千条)下的生效时间'],
    'Ingress 与 Gateway API')
